FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL := FALSE;
    motorDown : BOOL := FALSE;
    errorFlag : BOOL := FALSE;
END_VAR
VAR
    state        : INT := 0; // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    openBtnPrev  : BOOL := FALSE;
    closeBtnPrev : BOOL := FALSE;
END_VAR

// 边沿检测
VAR
    openRising  : BOOL;
    closeRising : BOOL;
END_VAR
openRising  := openBtn  AND NOT openBtnPrev;
closeRising := closeBtn AND NOT closeBtnPrev;

// 状态机逻辑
CASE state OF
    0: // IDLE
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openRising AND NOT openLimit THEN
            state := 1;
        ELSIF closeRising AND NOT closeLimit THEN
            state := 2;
        END_IF

    1: // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;
        IF obstacle THEN
            motorUp   := FALSE;
            errorFlag := TRUE;
            state := 3;
        ELSIF openLimit THEN
            motorUp := FALSE;
            state := 0;
        END_IF

    2: // CLOSING
        motorUp   := FALSE;
        motorDown := TRUE;
        IF obstacle THEN
            motorDown := FALSE;
            motorUp   := TRUE;
            state := 1;
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state := 0;
        END_IF

    3: // FAULT
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openBtn AND closeBtn THEN
            state         := 0;
            errorFlag     := FALSE;
            openBtnPrev   := TRUE;
            closeBtnPrev  := TRUE;
        END_IF
END_CASE

// 更新历史（FAULT 内部已更新按钮历史）
IF state <> 3 THEN
    openBtnPrev  := openBtn;
    closeBtnPrev := closeBtn;
END_IF
END_FUNCTION_BLOCK
